    표8_상담적용: [
        {"상황":"반복적인 죄의 패턴에서 벗어나지 못하는 분", "성경원리":"다메섹의 서너 가지 죄는 반복된 죄악이 심판을 불가피하게 만든다는 것을 보여준다.", "실제적용":"죄의 패턴을 인식하고 전문적 도움(상담, 영적 지도자)을 구하라. 반복되는 죄악은 혼자서는 끊기 어렵다"},
        {"상황":"과거의 피해로 용서가 어려운 분", "성경원리":"하나님이 모든 불의를 기억하시고 심판하신다. 인간이 복수하지 않아도 된다.", "실제적용":"용서는 가해자를 위한 것이 아니라 나 자신의 자유를 위한 것이다. 심판을 하나님께 맡기고 자신의 회복에 집중하라"},
        {"상황":"사회적 불의를 보며 무력감을 느끼는 분", "성경원리":"하나님은 다메섹의 죄를 기억하셨다가 반드시 심판하셨다. 역사의 불의는 반드시 하나님의 심판을 받는다.", "실제적용":"불의에 항거하되 결과는 하나님께 맡기라. 내가 할 수 있는 일을 하고 나머지는 신뢰하라"}
    ],
