    표5_매튜헨리: [
        {"영어원문":"He who handles the bow shall not stand—even the skilled archer, who can fight from a distance, finds no advantage when God is the opponent.", "한국어번역":"활을 가진 자도 서지 못할 것이다. 멀리서 싸울 수 있는 숙련된 궁수조차 하나님이 적이 될 때는 어떤 이점도 찾지 못한다.", "핵심통찰":"하나님이 대적이 되실 때 어떤 무기도 소용이 없다"},
        {"영어원문":"The swift of foot and the horseman—speed on foot or on horseback—cannot outpace the judgment of God; it follows every form of human flight.", "한국어번역":"발 빠른 자와 말 타는 자, 발로든 말로든 속도가 하나님의 심판을 앞지를 수 없다. 그것은 모든 형태의 인간적 도피를 따라온다.", "핵심통찰":"하나님의 심판은 모든 형태의 도피를 추적한다"},
        {"영어원문":"The comprehensive list of soldiers—archers, infantry, cavalry—leaves no military category exempt; when God fights against you, all martial skill becomes useless.", "한국어번역":"궁수, 보병, 기병의 포괄적 목록은 어떤 군사적 범주도 면제하지 않는다. 하나님이 당신에 대항해 싸우실 때 모든 전투 기술은 쓸모없게 된다.", "핵심통찰":"하나님이 대적이 되실 때 모든 군사 기술이 무용지물이 된다"}
    ],
