        {"상황":"죄악을 드러내는 것을 두려워하는 분", "성경원리":"벌거벗고 도망가는 것은 결국 모든 것이 드러나는 것이다. 자발적 고백이 강제적 노출보다 낫다.", "실제적용":"숨기려 하지 말고 자발적으로 하나님 앞에 모든 것을 드러내라. 고백은 치유의 시작이다"}
