        {"대지":"1대지: 수의 무력함 (열 명도 소용없다)", "내용":"사람들은 다수가 함께 있으면 안전하다고 생각한다. 그러나 하나님의 심판 앞에서 수효는 의미가 없다.", "예화_적용":"다수결로 진리를 정할 수 없는 것처럼, 군중 속에 있다고 심판을 피할 수 없다"},
        {"대지":"2대지: 관계의 무력함 (한 집이지만 다 죽음)", "내용":"가족이라는 가장 강한 유대도 심판을 막지 못한다. 영적인 문제는 개인과 공동체 각자가 하나님 앞에 서야 한다.", "예화_적용":"부모의 신앙이 자녀를 자동으로 구원하지 않는다"},
        {"대지":"3대지: 공동체적 책임 (연대의 책임)", "내용":"공동체의 죄는 공동체가 함께 책임진다. 우리 공동체의 죄에 나도 연대 책임이 있다.", "예화_적용":"교회 공동체의 죄와 회개에 대한 연대적 접근"},
        {"대지":"결론", "내용":"심판 앞에서 수나 관계에 의존하지 말고 각자 하나님 앞에 서라. 그리스도 안에서만 참된 구원이 있다.", "예화_적용":"개인 구원의 결단과 공동체적 거룩함 추구"}
