    표5_매튜헨리: [
        {"영어원문":"The desolation is so great that even the relatives collecting the bones dare not mention the name of God.", "한국어번역":"황폐함이 너무 커서 뼈를 거두는 친척들조차 감히 하나님의 이름을 언급하지 못한다.", "핵심통찰":"하나님의 심판의 철저함은 사람들로 그 이름조차 두려워하게 만든다"},
        {"영어원문":"In times of judgment, men are afraid to call on God, fearing more judgment.", "한국어번역":"심판의 때에 사람들은 더 큰 심판을 두려워하여 하나님을 부르기도 두려워한다.", "핵심통찰":"회개 없는 심판 의식은 더 큰 절망만 가져온다"},
        {"영어원문":"Hush! We must not call on the Lord — a sign of the greatest despair.", "한국어번역":"조용히! 우리가 여호와를 부르면 안 된다 — 이것은 가장 큰 절망의 표시다.", "핵심통찰":"하나님을 부를 수 없는 상황이 가장 비참한 상태다"}
    ],
