        {"대지":"서론", "내용":"지금 이 순간 우리는 자유롭게 하나님을 부를 수 있다. 그러나 심판의 날에는 그마저도 두려워 부르지 못하는 상황이 온다.", "예화_적용":"기도할 수 없는 상황을 상상해보기 - 기도의 특권"},
        {"대지":"1대지: 심판의 철저함 (마지막 한 사람)", "내용":"열 명 중 한 사람만 살아남아도 희망이 없다. 하나님의 심판은 철저하고 완전하다.", "예화_적용":"역사 속 완전한 멸망의 사례들 - 나인베 등"},
        {"대지":"2대지: 침묵의 공포 (잠잠하라)", "내용":"하나님의 이름을 부르지 못하는 것은 가장 극한의 절망. 지금 자유롭게 하나님을 부를 수 있는 것이 얼마나 큰 특권인가.", "예화_적용":"기도의 자유가 없는 박해 교회의 현실"},
        {"대지":"3대지: 회개의 기회 (지금이 부를 때)", "내용":"지금 여호와의 이름을 부를 수 있을 때 부르라. 행 2:21의 '누구든지 주의 이름을 부르는 자는 구원을 받으리라'는 지금의 말씀이다.", "예화_적용":"지금 기도하는 것이 회개와 구원의 시작"},
        {"대지":"결론", "내용":"하나님의 이름을 부를 수 있는 지금, 이 특권을 누리라. 심판의 날 부르지 못하기 전에, 지금 회개하고 구원을 구하라.", "예화_적용":"오늘 하나님의 이름을 부르며 기도로 시작하는 결단"}
