    표5_매튜헨리: [
        {"영어원문":"God called to contend by fire — a more dreadful judgment than the grasshoppers.", "한국어번역":"하나님이 불로 다투게 하시니 메뚜기보다 더 무서운 심판이다.", "핵심통찰":"경고를 무시하면 심판은 더 강해진다"},
        {"영어원문":"The fire devoured the great deep and did eat up a part of the land.", "한국어번역":"불이 큰 깊음을 삼키고 땅의 일부를 먹었다.", "핵심통찰":"하나님의 심판은 우주적 규모로 임할 수 있다"},
        {"영어원문":"Let first judgments be improved, lest worse come; better repent than repeat.", "한국어번역":"처음 심판에서 교훈을 얻으라, 더 나쁜 것이 오지 않도록. 반복하는 것보다 회개하는 것이 낫다.", "핵심통찰":"경고를 통해 배우는 자는 더 큰 심판을 피한다"}
    ],
