        {"대지":"서론", "내용":"첫 번째 심판이 유보되었는데 두 번째 심판이 준비된다. 왜인가? 이스라엘이 돌이키지 않았기 때문이다. 경고는 경고로 끝나지 않는다.", "예화_적용":"반복되는 경고를 무시한 결과의 이야기"},
        {"대지":"1대지: 심판의 강화 (메뚜기에서 불로)", "내용":"이스라엘이 첫 번째 경고를 무시했다. 그래서 더 강한 불 심판이 준비된다. 하나님의 경고를 가볍게 여기면 안 된다.", "예화_적용":"작은 경고를 무시했다가 큰 재앙을 만나는 현실"},
        {"대지":"2대지: 우주적 심판 (큰 바다를 삼킴)", "내용":"하나님의 심판은 인간의 상상을 초월하는 규모로 올 수 있다. 마지막 심판은 온 우주를 태우는 불로 온다.", "예화_적용":"기후 변화와 자연 재해 - 하나님의 경고로 읽는 눈"},
        {"대지":"3대지: 중보기도의 지속 (다시 기도함)", "내용":"두 번째 심판에도 아모스는 다시 중보기도를 드린다. 포기하지 않는 중보자의 모습이 우리의 본보기이다.", "예화_적용":"반복되는 어려움 속에서도 기도를 멈추지 않는 삶"},
        {"대지":"결론", "내용":"하나님의 경고를 가볍게 여기지 말라. 첫 번째 경고에 돌이키라. 중보기도의 사람이 되어 공동체를 지키라.", "예화_적용":"오늘 받은 하나님의 작은 경고에 즉시 반응하는 삶"}
