        {"교리":"인간의 약함과 하나님의 능력", "설명":"인간적 자격 없는 아모스를 통해 강력한 예언이 주어진 것은 하나님의 능력이 인간의 약함을 통해 나타남을 보여준다", "관련구절":"고후 12:9-10, 고전 2:3-5, 막 1:17"}
