        {"대지":"서론", "내용":"아모스는 소위 '낙하산'이 없었다. 유명한 선지자 학교 출신도, 대단한 배경도 없었다. 그냥 목자요 농부였다. 그런 그를 하나님이 불러 선지자로 세우셨다.", "예화_적용":"평범한 사람들이 위대한 일을 한 역사적 사례들"},
        {"대지":"1대지: 낮은 출신 (목자와 농부)", "내용":"목자는 당시 가장 낮은 직업 중 하나. 뽕나무 배양자는 더 낮은 직업. 하나님은 이런 사람을 부르신다.", "예화_적용":"하나님은 우리의 배경을 보시지 않는다 - 마음을 보신다(삼상 16:7)"},
        {"대지":"2대지: 소명의 진원 (하나님이 데려다가)", "내용":"15절의 '여호와께서 나를 데려다가.' 소명은 자신이 원해서 선택한 것이 아니라 하나님이 데려다 주신 것이다.", "예화_적용":"내 소명의 진원지는 어디인가? 내 결정인가, 하나님의 부르심인가?"},
        {"대지":"3대지: 소명의 권위 (하나님의 자격증)", "내용":"아마샤의 왕의 권위 vs 아모스의 하나님의 권위. 진정한 권위는 인간이 주는 것이 아니라 하나님이 주신다.", "예화_적용":"사역의 권위를 하나님에게서 받는 것의 의미"},
        {"대지":"결론", "내용":"당신의 배경이 아무리 낮아도 하나님이 부르시면 선지자가 된다. 하나님의 부르심을 두려워하지 말고 겸손히 받으라.", "예화_적용":"하나님의 부르심에 순종하는 결단"}
