        {"원어":"עַמִּי יִשְׂרָאֵל (암미 이스라엘)", "의미_문법":"내 백성 이스라엘 - 하나님과 이스라엘의 언약적 관계", "설교포인트":"심판도 사랑의 언약 관계 안에서 행해진다"}
