        {"항목":"여호와가 데려다가", "내용":"히브리어 '라카흐'는 하나님이 주도적으로 아모스를 취하는 행위를 나타냄. 인간의 자원이 아닌 하나님의 부르심", "목회적활용":"참된 소명은 하나님에게서 온다"},
        {"항목":"내 백성 이스라엘에게 예언하라", "내용":"심판 대상 이스라엘을 여전히 '내 백성'이라 부르신다. 심판 중에도 관계를 버리지 않으시는 하나님", "목회적활용":"하나님의 사랑은 심판 중에도 끊어지지 않는다"}
