    표5_매튜헨리: [
        {"영어원문":"The Lord took him as he followed the flock, showing that grace does not wait for our preparation.", "한국어번역":"주께서 그가 양떼를 따를 때에 데려가셨으니 은혜는 우리의 준비를 기다리지 않음을 보여준다.", "핵심통찰":"하나님의 소명은 우리의 준비 여부와 관계없이 온다"},
        {"영어원문":"Go, prophesy to My people Israel — they are still My people in the midst of judgment.", "한국어번역":"가서 내 백성 이스라엘에게 예언하라 — 그들은 심판 중에도 여전히 내 백성이다.", "핵심통찰":"하나님의 심판도 언약적 사랑의 표현이다"},
        {"영어원문":"The humblest employment is no bar to the highest calling.", "한국어번역":"가장 낮은 직업이 가장 높은 부르심을 막는 장벽이 되지 않는다.", "핵심통찰":"하나님은 가장 낮은 자를 통해 가장 높은 사명을 이루신다"}
    ],
