        {"대지":"서론", "내용":"아마샤는 아모스를 막으려 했다. 하지만 아모스의 마지막 말은 아마샤 개인에 대한 심판 선언이었다. 7장은 이렇게 끝난다.", "예화_적용":"진리를 막으려다 더 큰 심판을 받은 이야기"},
        {"대지":"1대지: 가정의 심판 (아내와 자녀)", "내용":"아마샤에게 가장 소중한 가정이 심판의 대상이 된다. 하나님은 가장 아픈 곳을 아신다.", "예화_적용":"가정이 얼마나 소중한가를 깨닫게 하는 심판의 역설"},
        {"대지":"2대지: 땅의 심판 (나누어짐)", "내용":"아마샤의 땅이 이방인에게 나누어진다. 하나님이 주신 것도 죄로 인해 빼앗길 수 있다.", "예화_적용":"하나님이 주신 것들을 소중히 여기는 청지기 삶"},
        {"대지":"3대지: 이스라엘의 포로됨 (역사적 성취)", "내용":"7장 전체의 결론: 이스라엘은 포로로 끌려갈 것이다. 이것이 BC 722년 성취되었다.", "예화_적용":"하나님의 예언의 역사적 신뢰성 - 성경을 믿을 수 있는 이유"},
        {"대지":"결론", "내용":"하나님의 말씀을 막으려 하지 말라. 심판은 구체적이고 철저하다. 지금 회개하고 돌아오는 것이 유일한 길이다.", "예화_적용":"2단계 완료 - 아모스 7장이 완성되었음을 기억하며 하나님의 말씀 앞에 서는 결단"}
