        {"교리":"계시의 다양성", "설명":"하나님은 일상적 사물(여름 실과)을 통해서도 심오한 진리를 계시하신다", "관련구절":"렘 1:11-14, 슥 1:7-8, 겔 1:1"},
        {"교리":"풍요 중의 심판", "설명":"풍성한 과일 바구니가 심판을 상징하는 것은 외적 번영이 하나님의 축복을 보장하지 않음을 보여준다", "관련구절":"눅 12:19-20, 시 49:16-17, 잠 11:28"}
